import{_ as t,a as o}from"./chunks/demo_02.CQmw40B0.js";import{_ as r,Y as i,o as n,c as l,aq as c,H as s}from"./chunks/framework.d4q-Q6bs.js";import"./chunks/theme.x-68MGni.js";const q=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/guide/home.md","filePath":"zh-cn/guide/home.md"}'),p={name:"zh-cn/guide/home.md"};function u(h,e,d,m,_,b){const a=i("NolebaseGitChangelog");return n(),l("div",null,[e[0]||(e[0]=c('<h1 id="introduction" tabindex="-1">介绍 <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><blockquote><p><code>PanguText</code> 是一个中日韩 (CJK) 与英文单词、半角数字排版的解决方案。</p></blockquote><h2 id="background" tabindex="-1">背景 <a class="header-anchor" href="#background" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>这个项目的起因是因为直到目前为止还没有一套公开的方案能够完美解决中文、日文、韩文与英文之间的排版问题， 正常情况下我们将 CJK (即中日韩) 与英文混排的时候，都会涉及到美观性问题，这算是一个历史遗留问题，全角文字与半角文字之间的书写规范不一样。虽然现在 W3C 规定了 CJK 排版规范， 但是还是仅有部分愿意遵守排版要求的个人或企业选择了这种方案。</p><p>目前已知的厂商解决方案如下</p><ul><li>Apple 全系 (iOS、iPadOS、macOS、tvOS、watchOS) 文本排版解决方案</li><li>小米 (HyperOS) 文本排版优化</li><li>OrginOS 基于字体的文本排版优化</li></ul><p>但是这些方案都是封闭的，无法在其他平台上使用，因此我们希望能够提供一套开源的解决方案，能够适应各种场景、侵入性低且更容易集成，让更多的开发者能够使用这个方案来解决文本排版问题。</p><p>本项目得以进行的主要来源为 <a href="https://github.com/vinta/pangu.js" target="_blank" rel="noreferrer">pangu.js</a>，它提供了一套 CJK 排版的正则，我们对其加以优化，实现各个平台不需要插入空格字符即可格式化文本排版的效果， 衷心感谢这个项目的开发者提供的方案，我们在这个方案上加以扩展，提供了更多解决方案的可能性。</p><h2 id="effects" tabindex="-1">效果 <a class="header-anchor" href="#effects" aria-label="Permalink to &quot;效果&quot;">​</a></h2><p>如你所见，PanguText 的排版方案并不是向 CJK 与英文单词之间插入空格来完成，而是使用每个平台对应的处理方案自动在这些字符之间添加空白间距来达到排版效果以达到最低的侵入性。</p><blockquote><p>应用前 (上)、应用后 (下)</p></blockquote><img src="'+t+'" width="300"><blockquote><p>动态应用</p></blockquote><img src="'+o+'" width="480"><p>PanguText 支持动态应用，它允许你在输入文本的同时动态为每个字符添加空白间距。</p><div class="tip custom-block"><p class="custom-block-title">开发者的观点</p><p>我个人依然不提倡手动为 CJK 和英文字符之间添加空格来达到排版美化效果 (如果软件、系统本身支持这种排版美化方式)， 因为空格在不同的字体中的间距也是不一样的，这会造成排版效果出现问题，也会被加入本不应该出现的空格字符，在某些场景下，例如网址、文件名或者带有 “#” 的话题标签，不允许出现这些空格。但是，在一些特殊场景，例如代码的注释中，涉及到代码的说明文档，建议加入空格，因为这些范围内可能不会有排版格式化工具。</p><p>还有一点就是，在不同的语言中使用不同的标点符号，切忌全角和半角标点符号混用，如果一定要使用半角标点符号来标记全角文字，在句子未结束时将半角符号向后推进一个空格补全字符空间 (英文也是如此)。</p></div><h2 id="language-requirement" tabindex="-1">语言要求 <a class="header-anchor" href="#language-requirement" aria-label="Permalink to &quot;语言要求&quot;">​</a></h2><p>推荐使用 Kotlin 作为首选开发语言，本项目完全使用 Kotlin 编写，在部分内容上对 Java 做了兼容处理，但也许无法做到完全兼容。</p><p>文档全部的 Demo 示例代码都将使用 Kotlin 进行描述，如果你完全不会使用 Kotlin，那么你将有可能无法获得最佳使用体验。</p><h2 id="contribution" tabindex="-1">功能贡献 <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;功能贡献&quot;">​</a></h2><p>本项目的维护离不开各位开发者的支持和贡献，目前这个项目处于初期阶段，可能依然存在一些问题或者缺少你需要的功能， 如果可能，欢迎提交 PR 为此项目贡献你认为需要的功能或前往 <a href="https://github.com/BetterAndroid/PanguText/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 向我们提出建议。</p>',21)),s(a)])}const P=r(p,[["render",u]]);export{q as __pageData,P as default};
